    event=json.loads((p/'flight_result.json').read_text());consumer=[json.loads(s) for s in (p/'consumer.jsonl').read_text().splitlines()];pub_no_effect=all(not x['learned_control_enabled'] and not np.any(x['applied_ff_enu']) and np.array_equal(x['original_acceleration_enu'],x['final_acceleration_enu']) for x in commands);native_no_effect=all(not x['mass_updated'] and not np.any(x['dr']) and not np.any(x['dj']) and not np.any(x['correction']) for x in consumer);age=(gps.receive_us.to_numpy()*1000-gps.source_ns.to_numpy())*1e-6
